import{_ as t,o as e,c as o,a3 as n}from"./chunks/framework.BlfGB29P.js";const u=JSON.parse('{"title":"Python 异步与 HTTP","description":"","frontmatter":{"title":"Python 异步与 HTTP"},"headers":[],"relativePath":"py-agent/foundations/python-async-http/index.md","filePath":"py-agent/foundations/python-async-http/index.md","lastUpdated":1785291406000}'),i={name:"py-agent/foundations/python-async-http/index.md"};function l(r,a,c,d,h,p){return e(),o("div",null,[...a[0]||(a[0]=[n('<h1 id="python-异步与-http" tabindex="-1">Python 异步与 HTTP <a class="header-anchor" href="#python-异步与-http" aria-label="Permalink to &quot;Python 异步与 HTTP&quot;">​</a></h1><blockquote><p>作者：codex-gpt-sol-5.6</p></blockquote><p>本分组解释模型客户端依赖的 I/O 运行机制。协程让一个线程在等待网络时切换到其他工作；Task 和 <code>TaskGroup</code> 为并发工作建立所有权、失败和取消边界；HTTP 客户端在此基础上管理连接、请求、响应和关闭生命周期。</p><h2 id="_1-本分组的作用" tabindex="-1">1. 本分组的作用 <a class="header-anchor" href="#_1-本分组的作用" aria-label="Permalink to &quot;1. 本分组的作用&quot;">​</a></h2><p>“使用了 <code>async</code>”不等于程序自动并发，也不等于阻塞操作已经消失。模型调用通常耗时主要来自网络等待，应用必须理解哪个协程暂停、哪个任务拥有取消责任、客户端何时关闭，否则会出现串行等待、孤儿任务、连接泄漏和超时后仍继续工作。</p><h2 id="_2-学习目标" tabindex="-1">2. 学习目标 <a class="header-anchor" href="#_2-学习目标" aria-label="Permalink to &quot;2. 学习目标&quot;">​</a></h2><p>完成本分组后，你应能够：</p><ol><li>区分协程函数、协程对象、Task 和事件循环。</li><li>用时间线解释 <code>await</code> 何时暂停当前协程、事件循环何时恢复它。</li><li>使用 <code>TaskGroup</code> 让并发任务共享清楚的成功、失败和取消生命周期。</li><li>正确处理 <code>CancelledError</code>、超时、清理和多异常。</li><li>使用 Semaphore 和有界 Queue 限制并发并建立背压。</li><li>使用同步或异步 HTTPX 客户端发送请求、分类错误并可靠关闭连接池。</li><li>使用 <code>MockTransport</code> 测试 HTTP 边界而不访问真实服务。</li></ol><h2 id="_3-学习顺序" tabindex="-1">3. 学习顺序 <a class="header-anchor" href="#_3-学习顺序" aria-label="Permalink to &quot;3. 学习顺序&quot;">​</a></h2><ol><li><a href="/py-agent/foundations/python-async-http/coroutines-await-event-loop">协程与事件循环</a></li><li><a href="/py-agent/foundations/python-async-http/structured-concurrency-cancellation">结构化并发与取消</a></li><li><a href="/py-agent/foundations/python-async-http/http-client">HTTP 客户端</a></li></ol><p>第一篇只建立单个协程的暂停与恢复模型；第二篇才引入 Task 所有权、并发和取消；第三篇把这些机制应用到真实 I/O 客户端。不要跳过前两篇直接把同步调用机械改成 <code>await</code>。</p><h2 id="_4-内容边界" tabindex="-1">4. 内容边界 <a class="header-anchor" href="#_4-内容边界" aria-label="Permalink to &quot;4. 内容边界&quot;">​</a></h2><p>本分组不展开线程池和进程池内部实现、异步生成器、HTTP 协议帧、OAuth、自动重试、WebSocket 服务端和模型 SDK。模型请求对象、流式模型事件和模型调用可靠性在“模型应用基础”中继续讲解。</p>',13)])])}const T=t(i,[["render",l]]);export{u as __pageData,T as default};
